class Solution {
    public int numDistinct(String s, String t) {
        int m = s.length();
        int n = t.length();
        long[][] dp = new long[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            dp[i][0] = 1;
        }
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                dp[i][j] = dp[i - 1][j];
                if (s.charAt(i - 1) == t.charAt(j - 1)) {
                    dp[i][j] += dp[i - 1][j - 1];
                }
            }
        }
        return (int) dp[m][n];
    }
}

class Solution {
    public int numDistinct(String s, String t) {
        int n = t.length();
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 0; i < s.length(); i++) {
            for (int j = n; j >= 1; j--) {
                if (s.charAt(i) == t.charAt(j - 1)) {
                    dp[j] += dp[j - 1];
                }
            }
        }
        return (int) dp[n];
    }
}

class Solution {
    public int numDistinct(String s, String t) {
        long[][] memo = new long[s.length()][t.length()];
        for (long[] row : memo) {
            java.util.Arrays.fill(row, -1);
        }
        return (int) count(s, t, 0, 0, memo);
    }

    private long count(String s, String t, int i, int j, long[][] memo) {
        if (j == t.length()) {
            return 1;
        }
        if (i == s.length()) {
            return 0;
        }
        if (s.length() - i < t.length() - j) {
            return 0;
        }
        if (memo[i][j] != -1) {
            return memo[i][j];
        }
        long ways = count(s, t, i + 1, j, memo);
        if (s.charAt(i) == t.charAt(j)) {
            ways += count(s, t, i + 1, j + 1, memo);
        }
        memo[i][j] = ways;
        return ways;
    }
}

class Solution {
    public int numDistinct(String s, String t) {
        int m = s.length();
        int n = t.length();
        long[][] suffix = new long[m + 1][n + 1];
        for (int i = 0; i <= m; i++) {
            suffix[i][n] = 1;
        }
        for (int i = m - 1; i >= 0; i--) {
            for (int j = n - 1; j >= 0; j--) {
                suffix[i][j] = suffix[i + 1][j];
                if (s.charAt(i) == t.charAt(j)) {
                    suffix[i][j] += suffix[i + 1][j + 1];
                }
            }
        }
        return (int) suffix[0][0];
    }
}

class Solution {
    public int numDistinct(String s, String t) {
        int n = t.length();
        java.util.List<Integer>[] positions = new java.util.ArrayList[128];
        for (int i = 0; i < positions.length; i++) {
            positions[i] = new java.util.ArrayList<>();
        }
        for (int j = 0; j < n; j++) {
            positions[t.charAt(j)].add(j + 1);
        }
        long[] dp = new long[n + 1];
        dp[0] = 1;
        for (int i = 0; i < s.length(); i++) {
            char ch = s.charAt(i);
            java.util.List<Integer> matches = positions[ch];
            for (int k = matches.size() - 1; k >= 0; k--) {
                int j = matches.get(k);
                dp[j] += dp[j - 1];
            }
        }
        return (int) dp[n];
    }
}
